package com.bank;public sealed abstract class BankAccount permits SavingsAccount,CurrentAccount,LoanAccount{final long accountNumber;final int customerId;double balance;String status;BankAccount(long n,int c,double b,String s){accountNumber=n;customerId=c;balance=b;status=s;}abstract String type();abstract double minimum();public String toString(){return accountNumber+" | customer="+customerId+" | "+type()+" | Rs. "+balance+" | "+status;}}
